public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> res = new ArrayList<>();
    if (nums == null) return res;
    int n = nums.length;
    class Backtrack {
        void dfs(int start) {
            if (start == n) {
                List<Integer> perm = new ArrayList<>(n);
                for (int num : nums) perm.add(num);
                res.add(perm);
                return;
            }
            for (int i = start; i < n; i++) {
                int tmp = nums[start];
                nums[start] = nums[i];
                nums[i] = tmp;
                dfs(start + 1);
                tmp = nums[start];
                nums[start] = nums[i];
                nums[i] = tmp;
            }
        }
    }
    new Backtrack().dfs(0);
    return res;
}

public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    // If only one string, the largest substring is the string itself
    if (strings.size() == 1) {
        return strings.get(0).length();
    }
    // Find the shortest string to reduce candidate substrings
    int minIndex = 0;
    int minLen = strings.get(0).length();
    for (int i = 1; i < strings.size(); i++) {
        int len = strings.get(i).length();
        if (len < minLen) {
            minLen = len;
            minIndex = i;
        }
    }
    String base = strings.get(minIndex);
    int maxLen = 0;
    int baseLen = base.length();
    // Precompute reverse of base for efficiency
    for (int start = 0; start < baseLen; start++) {
        for (int end = start + 1; end <= baseLen; end++) {
            String sub = base.substring(start, end);
            int subLen = end - start;
            if (subLen <= maxLen) {
                continue; // cannot beat current max
            }
            String rev = new StringBuilder(sub).reverse().toString();
            boolean ok = true;
            for (String s : strings) {
                if (!(s.contains(sub) || s.contains(rev))) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                maxLen = subLen;
            }
        }
    }
    return maxLen;
}

public static int countOilDeposits(char[][] grid) {
    if (grid == null || grid.length == 0 || grid[0].length == 0) {
        return 0;
    }
    int rows = grid.length;
    int cols = grid[0].length;
    boolean[][] visited = new boolean[rows][cols];
    int count = 0;
    int[] dx = {-1, -1, -1, 0, 0, 1, 1, 1};
    int[] dy = {-1, 0, 1, -1, 1, -1, 0, 1};

    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            if (grid[i][j] == '@' && !visited[i][j]) {
                count++;
                // DFS stack
                java.util.Deque<int[]> stack = new java.util.ArrayDeque<>();
                stack.push(new int[]{i, j});
                visited[i][j] = true;
                while (!stack.isEmpty()) {
                    int[] cell = stack.pop();
                    int x = cell[0];
                    int y = cell[1];
                    for (int dir = 0; dir < 8; dir++) {
                        int nx = x + dx[dir];
                        int ny = y + dy[dir];
                        if (nx >= 0 && nx < rows && ny >= 0 && ny < cols &&
                            grid[nx][ny] == '@' && !visited[nx][ny]) {
                            visited[nx][ny] = true;
                            stack.push(new int[]{nx, ny});
                        }
                    }
                }
            }
        }
    }
    return count;
}

