public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Helper to convert coordinate array to a unique string key
    java.util.function.Function<int[], String> coordToKey = (int[] coord) -> {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < coord.length; i++) {
            if (i > 0) sb.append(',');
            sb.append(coord[i]);
        }
        return sb.toString();
    };

    String startKey = coordToKey.apply(start);
    String endKey = coordToKey.apply(end);

    // If start and end are the same point
    if (startKey.equals(endKey)) {
        return "can be travelled";
    }

    // Build adjacency map from paths
    java.util.Map<String, java.util.List<String>> graph = new java.util.HashMap<>();

    for (int[] path : paths) {
        if (path.length != 2 * n) {
            // Invalid path length; skip or handle error
            continue;
        }
        int[] coord1 = new int[n];
        int[] coord2 = new int[n];
        System.arraycopy(path, 0, coord1, 0, n);
        System.arraycopy(path, n, coord2, 0, n);
        String key1 = coordToKey.apply(coord1);
        String key2 = coordToKey.apply(coord2);

        graph.computeIfAbsent(key1, k -> new java.util.ArrayList<>()).add(key2);
        graph.computeIfAbsent(key2, k -> new java.util.ArrayList<>()).add(key1);
    }

    // BFS to check connectivity
    java.util.Queue<String> queue = new java.util.LinkedList<>();
    java.util.Set<String> visited = new java.util.HashSet<>();

    queue.add(startKey);
    visited.add(startKey);

    while (!queue.isEmpty()) {
        String current = queue.poll();
        java.util.List<String> neighbors = graph.get(current);
        if (neighbors == null) continue;
        for (String neighbor : neighbors) {
            if (neighbor.equals(endKey)) {
                return "can be travelled";
            }
            if (!visited.contains(neighbor)) {
                visited.add(neighbor);
                queue.add(neighbor);
            }
        }
    }

    return "cannot be travelled";
}

