public boolean canArrange(int[] arr, int k) {
    if (k <= 0) return false; // divisor must be positive
    int n = arr.length;
    if (n % 2 != 0) return false; // must be even number of elements

    int[] freq = new int[k];
    for (int num : arr) {
        int r = ((num % k) + k) % k; // handle negative numbers
        freq[r]++;
    }

    // Check remainder 0
    if (freq[0] % 2 != 0) return false;

    // If k is even, check remainder k/2
    if (k % 2 == 0) {
        if (freq[k / 2] % 2 != 0) return false;
    }

    // Check other remainders
    int limit = k / 2;
    for (int r = 1; r <= limit; r++) {
        if (r == k - r) continue; // already handled when k even
        if (freq[r] != freq[k - r]) return false;
    }

    return true;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    java.util.List<Integer>[] graph = new java.util.ArrayList[n];
    for (int i = 0; i < n; i++) {
        graph[i] = new java.util.ArrayList<Integer>();
    }
    for (int[] e : edges) {
        int u = e[0];
        int v = e[1];
        graph[u].add(v);
        graph[v].add(u);
    }
    int[] parent = new int[n];
    java.util.Arrays.fill(parent, -1);
    int[] order = new int[n];
    int idx = 0;
    java.util.Stack<Integer> stack = new java.util.Stack<Integer>();
    stack.push(0);
    while (!stack.isEmpty()) {
        int node = stack.pop();
        order[idx++] = node;
        for (int nei : graph[node]) {
            if (nei == parent[node]) continue;
            parent[nei] = node;
            stack.push(nei);
        }
    }
    int total = 0;
    boolean[] has = new boolean[n];
    for (int i = n - 1; i >= 0; i--) {
        int node = order[i];
        boolean nodeHas = hasApple[node];
        for (int nei : graph[node]) {
            if (nei == parent[node]) continue;
            if (has[nei]) {
                total += 2;
                nodeHas = true;
            }
        }
        has[node] = nodeHas;
    }
    return total;
}

public String sortString(String s) {
    int[] count = new int[26];
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        count[c - 'a']++;
    }
    int total = s.length();
    StringBuilder sb = new StringBuilder(total);
    while (total > 0) {
        // Ascending pass
        int i = 0;
        while (i < 26 && count[i] == 0) i++;
        if (i == 26) break;
        sb.append((char) ('a' + i));
        count[i]--;
        total--;
        for (int j = i + 1; j < 26; j++) {
            if (count[j] > 0) {
                sb.append((char) ('a' + j));
                count[j]--;
                total--;
            }
        }
        if (total == 0) break;
        // Descending pass
        int k = 25;
        while (k >= 0 && count[k] == 0) k--;
        if (k < 0) break;
        sb.append((char) ('a' + k));
        count[k]--;
        total--;
        for (int j = k - 1; j >= 0; j--) {
            if (count[j] > 0) {
                sb.append((char) ('a' + j));
                count[j]--;
                total--;
            }
        }
    }
    return sb.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n < 2) return false;
    int totalSum = 0;
    for (int num : nums) totalSum += num;
    @SuppressWarnings("unchecked")
    java.util.HashSet<Integer>[] sumsBySize = new java.util.HashSet[n + 1];
    for (int i = 0; i <= n; i++) sumsBySize[i] = new java.util.HashSet<>();
    sumsBySize[0].add(0);
    for (int num : nums) {
        for (int k = n - 1; k >= 1; k--) {
            for (int s : sumsBySize[k - 1]) {
                sumsBySize[k].add(s + num);
            }
        }
    }
    for (int k = 1; k <= n / 2; k++) {
        if ((totalSum * k) % n != 0) continue;
        int target = (totalSum * k) / n;
        if (sumsBySize[k].contains(target)) return true;
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) return 0;
    if (n == 1) return 0; // can start at the top directly
    int prev2 = cost[0];
    int prev1 = cost[1];
    for (int i = 2; i < n; i++) {
        int curr = cost[i] + Math.min(prev1, prev2);
        prev2 = prev1;
        prev1 = curr;
    }
    return Math.min(prev1, prev2);
}

