public int minInsertions(String s) {
    int balance = 0; // number of unmatched '('
    int insertions = 0; // number of insertions needed
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            balance++;
        } else { // c == ')'
            if (balance > 0) {
                balance--; // match with an existing '('
            } else {
                // need an extra '(' before this ')'
                insertions++;
                // balance remains 0 after matching the inserted '(' with this ')'
            }
        }
    }
    // any remaining unmatched '(' need ')' insertions
    insertions += balance;
    return insertions;
}

