private int dfs(int index, java.util.Set<String> used, String s, int n) {
    if (index == n) {
        return 0;
    }
    int max = 0;
    for (int end = index + 1; end <= n; end++) {
        String sub = s.substring(index, end);
        if (!used.contains(sub)) {
            used.add(sub);
            int count = 1 + dfs(end, used, s, n);
            if (count > max) {
                max = count;
            }
            used.remove(sub);
        }
    }
    return max;
}

