public String getSmallestString(int n, int k) {
    // The minimum possible sum is n (all 'a's), the maximum is 26*n (all 'z's).
    // We start with all 'a's and add the necessary value from the end to keep the string lexicographically smallest.
    int remaining = k - n; // how much extra value we need to distribute
    char[] result = new char[n];
    // Initialize all positions with 'a'
    for (int i = 0; i < n; i++) {
        result[i] = 'a';
    }
    // Distribute the remaining value starting from the last character
    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        int add = Math.min(25, remaining); // each position can increase by at most 25 (from 'a' to 'z')
        result[i] = (char) ('a' + add);
        remaining -= add;
    }
    return new String(result);
}

